package mx.com.mesaregia.cotizaciones.application.service.impl;
import mx.com.mesaregia.cotizaciones.api.request.*; import mx.com.mesaregia.cotizaciones.api.response.VersionResponse; import mx.com.mesaregia.cotizaciones.application.service.CotizacionVersionService; import mx.com.mesaregia.cotizaciones.domain.entity.*; import mx.com.mesaregia.cotizaciones.domain.enums.*; import mx.com.mesaregia.cotizaciones.exception.*; import mx.com.mesaregia.cotizaciones.integration.client.CatalogoPricingPort; import mx.com.mesaregia.cotizaciones.mapper.CotizacionMapper; import mx.com.mesaregia.cotizaciones.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class CotizacionVersionServiceImpl implements CotizacionVersionService { private final CotizacionVersionRepository vr;private final CotizacionDetalleRepository dr;private final CotizacionSupport s;private final CatalogoPricingPort catalogo;
 public CotizacionVersionServiceImpl(CotizacionVersionRepository vr,CotizacionDetalleRepository dr,CotizacionSupport s,CatalogoPricingPort catalogo){this.vr=vr;this.dr=dr;this.s=s;this.catalogo=catalogo;}
 @Transactional public VersionResponse recotizar(Long id,RecotizarRequest r){var q=s.get(id);if(q.getEstadoGeneral()==EstadoCotizacion.CANCELADA||q.getEstadoGeneral()==EstadoCotizacion.RECHAZADA||q.getEstadoGeneral()==EstadoCotizacion.VENCIDA)throw new ConflictException("No puede recotizarse una cotización terminal");catalogo.validarListaPrecio(r.idListaPrecio());int n=Optional.ofNullable(vr.maxNumero(id)).orElse(0)+1;var v=new CotizacionVersion();v.setIdCotizacion(id);v.setNumeroVersion(n);v.setFolioVersion(q.getFolio()+"-V"+n);v.setIdListaPrecioExterno(r.idListaPrecio());v.setIdUsuarioCreacionExterno(r.idUsuario());v=vr.save(v);if(r.idVersionOrigen()!=null){var o=s.version(id,r.idVersionOrigen());for(var d:dr.findByIdCotizacionVersionOrderByOrdenAsc(o.getId())){var x=new CotizacionDetalle();x.setIdCotizacionVersion(v.getId());x.setTipoConcepto(d.getTipoConcepto());x.setIdConceptoExterno(d.getIdConceptoExterno());x.setCodigoSnapshot(d.getCodigoSnapshot());x.setNombreSnapshot(d.getNombreSnapshot());x.setCantidad(d.getCantidad());x.setPrecioUnitarioAplicado(d.getPrecioUnitarioAplicado());x.setPorcentajeAdicionalAplicado(d.getPorcentajeAdicionalAplicado());x.setOrden(d.getOrden());dr.save(x);}}s.history(id,v.getId(),"VERSION_CREADA",null,EstadoVersion.BORRADOR.name(),"Recotización V"+n,r.idUsuario());return CotizacionMapper.version(v,dr.findByIdCotizacionVersionOrderByOrdenAsc(v.getId()));}
 @Transactional public VersionResponse actualizar(Long id,Long idVersion,VersionUpsertRequest r){var v=s.version(id,idVersion);if(v.getEstadoVersion()!=EstadoVersion.BORRADOR)throw new ConflictException("Solo una versión BORRADOR puede editarse");if(r.version()!=null&&!Objects.equals(v.getVersion(),r.version()))throw new ConflictException("Versión de concurrencia desactualizada");catalogo.validarListaPrecio(r.idListaPrecio());v.setIdListaPrecioExterno(r.idListaPrecio());v.setObservaciones(r.observaciones());v=vr.saveAndFlush(v);dr.deleteByIdCotizacionVersion(v.getId());int orden=1;for(var item:r.conceptos()){var precio=catalogo.resolver(r.idListaPrecio(),item.tipoConcepto(),item.idConcepto());var d=new CotizacionDetalle();d.setIdCotizacionVersion(v.getId());d.setTipoConcepto(item.tipoConcepto());d.setIdConceptoExterno(item.idConcepto());d.setCodigoSnapshot(precio.codigo());d.setNombreSnapshot(precio.nombre());d.setCantidad(item.cantidad());d.setPrecioUnitarioAplicado(precio.precioUnitarioAplicado());d.setPorcentajeAdicionalAplicado(precio.porcentajeAdicionalAplicado());d.setOrden(orden++);dr.save(d);}s.history(id,v.getId(),"VERSION_ACTUALIZADA",EstadoVersion.BORRADOR.name(),EstadoVersion.BORRADOR.name(),null,r.idUsuario());return CotizacionMapper.version(v,dr.findByIdCotizacionVersionOrderByOrdenAsc(v.getId()));}
}
